using System;using System.IO;using System.Text;using System.Linq;
class AnalysisTests {
 static void A(bool v,string m){if(!v)throw new Exception(m);}
 static void Main(){string root=Path.Combine(Path.GetTempPath(),"analysis-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{A(Analyzer.Architectures("AnyCPU managed").Length==2,"AnyCPU probes both architectures");A(Analyzer.Architectures("ARM64").Length==0,"unknown ABI not probed");byte[] data=new byte[1024*1024+700];byte[] first=Encoding.ASCII.GetBytes("\0SteamFriends018\0STEAMUGC_INTERFACE_VERSION021\0SteamFriends018X\0");Buffer.BlockCopy(first,0,data,1024*1024-25,first.Length);byte[] wide=Encoding.Unicode.GetBytes("\0SteamClient023\0STEAMINVENTORY_INTERFACE_V003\0");Buffer.BlockCopy(wide,0,data,1024*1024+101,wide.Length);string path=Path.Combine(root,"Fixture.dll");File.WriteAllBytes(path,data);var b=Analyzer.ReadBinary(path,root);A(b.Evidence.Any(e=>e.Interface=="SteamFriends018"),"ASCII across chunk boundary");A(b.Evidence.Count(e=>e.Interface=="SteamFriends018")==1,"overlap dedup and false-prefix rejection");A(b.Evidence.Any(e=>e.Interface=="SteamClient023"&&e.Kind=="UTF-16 string"),"odd aligned UTF16");A(b.Evidence.Any(e=>e.Interface=="STEAMINVENTORY_INTERFACE_V003"),"inventory version");A(b.Evidence.Any(e=>e.Interface=="STEAMUGC_INTERFACE_VERSION021"),"UGC version");foreach(string bits in new[]{"32","64"}){string dll=Path.Combine(Core.Base,"modules/gmod",bits=="32"?"steam_api.dll":"steam_api64.dll");var pe=Analyzer.ReadBinary(dll,Core.Base);A(pe.Error==null,"valid PE "+bits+": "+pe.Error);A(pe.Architecture==(bits=="32"?"x86":"x64"),"PE machine");A(pe.Exports.Contains("SteamAPI_InitFlat"),"Steam exports");A(pe.Imports.Any(x=>x.Contains("original.dll")),"Steam original import");}var report=new AnalysisReport{Game="Fixture",Root=root,Steam="NotRunning"};report.Files.Add(b);report.Probes["x86|SteamFriends018"]="UNKNOWN: probe failed";string text=Analyzer.Render(report);A(text.Contains("UNKNOWN")&&text.Contains("静态字符串")&&text.Contains("SteamFriends017"),"report preserves uncertainty and fallback candidates");Console.WriteLine("PASS: chunk boundary, dedup, negative match, UTF16 alignment, interface families, x86/x64 PE metadata, Steam exports/imports, report uncertainty.");}finally{Directory.Delete(root,true);}}
}
